local Test={}
function Test.run()
 local B=require('biology');local G=require('genome');local V=require('vessels');local M=require('desktop_model');local D=require('workshop_docking');local W=require('cell_workshop');local F=require('physical_cells');local Host=require('desktop_host');local C=require('desktop_controls');local S=require('persistence')
 Host.monitors={{id='test',x=0,y=0,w=1920,h=1080,dpi=96}};local failed,lines=0,{}
 local function test(name,fn) local ok,why=xpcall(fn,debug.traceback);lines[#lines+1]=(ok and 'PASS ' or 'FAIL ')..name;if not ok then failed=failed+1;lines[#lines+1]=tostring(why) end end
 local function fixture() local s=B.new(1);V.ensure(s);M.ensure(s);F.ensure(s);local station=M.add(s,'workstation','w',nil,100,100);local _,_,input=F.buy(s,'blank');V.add(s,4,true);local output=s.vessels[#s.vessels];local src=M.add(s,'vial',input.id);local dst=M.add(s,'vial',output.id);local record={id=B.id(s),name='Chosen DNA',genome=G.new(G.rng(22250963))};s.materials[#s.materials+1]=record;local vial=M.add(s,'dna',record.id);assert(D.attach(s,station.id,src.id,'input'));assert(D.attach(s,station.id,dst.id,'output'));return s,station,input,output,vial,record end
 test('Dropping DNA onto a collapsed machine opens a separate DNA dock without replacing its cell input',function() local s,w,input,output,vial,record=fixture();local source=w.config.docks.input;local hit,ok=D.drop(s,vial,{x=w.x+100,y=w.y+100},Host.monitors);assert(hit and ok and w.config.expanded and w.config.docks.input==source and w.config.docks.dna==vial.id);assert(D.dna(s,w.id)==record and V.count(input)==1 and V.count(output)==0) end)
 test('Physical attached DNA installs its exact genome and consumes only the blank cell',function() local s,w,input,output,vial,record=fixture();assert(D.attach(s,w.id,vial.id,'dna'));w.config.genomeId=-999;local before=S.encode(record);assert(W.install(s,w.id));assert(V.count(input)==0 and V.count(output)==1);assert(G.hash(output.contents[1].cell.genome)==G.hash(record.genome));assert(S.encode(record)==before and w.config.docks.dna==vial.id) end)
 test('Occupied DNA docks and wrong or unavailable records reject without changing attachments or cells',function() local s,w,input,output,vial,record=fixture();assert(D.attach(s,w.id,vial.id,'dna'));local other=M.add(s,'dna',record.id);assert(not D.attach(s,w.id,other.id,'dna'));assert(not D.attach(s,w.id,M.find(s,w.config.docks.input).id,'dna'));s.materials={};assert(not W.install(s,w.id));assert(V.count(input)==1 and V.count(output)==0 and w.config.docks.dna==vial.id) end)
 test('DNA dock references and exact genome survive save/load and detach cleanly',function() local s,w,input,output,vial,record=fixture();assert(D.attach(s,w.id,vial.id,'dna'));local restored=assert(S.decode('return '..S.encode(s),B));local dna,object=D.dna(restored,w.id);assert(dna.id==record.id and object.id==vial.id and G.hash(dna.genome)==G.hash(record.genome));assert(D.detach(restored,vial.id));assert(not D.station(restored,w.id).config.docks.dna and #restored.materials==1) end)
 test('DNA dock is visible in the real workshop controls and can be detached directly',function() local s,w,input,output,vial,record=fixture();assert(D.attach(s,w.id,vial.id,'dna'));C.expand(s,w);D.layout(s,w,Host.monitors);local Art=require('desktop_art');local Z=require('desktop_depth');local canvas=love.graphics.newCanvas(1070,660);love.graphics.push('all');love.graphics.setCanvas(canvas);love.graphics.clear(.035,.055,.065);for _,o in ipairs(Z.ordered(s)) do if o==w or o.config.workshop==w.id then love.graphics.push();love.graphics.translate(o.x-w.x+10,o.y-w.y+10);Art.draw(s,o);love.graphics.pop() end end;love.graphics.setCanvas();local root=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource();local f=assert(io.open(root..'/workshop-dna-preview.png','wb'));f:write(canvas:newImageData():encode('png'):getString());f:close();love.graphics.pop();local detach;for _,hit in ipairs(C.hits[w.id]) do if hit.id=='Detach' then detach=hit end end;assert(detach);detach.fn();assert(not w.config.docks.dna and #s.materials==1) end)
 local result=table.concat(lines,'\n')..string.format('\n%d checks; %d failures.\n',#lines,failed);local root=love.filesystem.isFused() and love.filesystem.getSourceBaseDirectory() or love.filesystem.getSource();local f=assert(io.open(root..'/workshop-dna-test-results.txt','wb'));f:write(result);f:close();assert(failed==0,result);return result
end
return Test
